def is_prime(n):
    """A simple program which should return True if n is 
    a prime number and should return False otherwise.

    Examples:
    for is_prime(2) == True
    for is_prime(15) == False

    """
    if n <= 1:
        return False

    for i in range(int(n ** 0.5) + 1):
        if n % i == 0:
            n = n % i
        if n == 0:
            return True

    return True

